@If(Standard = ""; 		@Return(@Do(@Command([EditGotoField];"Standard");		@Prompt([Ok];"Missing Value"; "Please select the standard requirement before proceeding!")));"");
@If(Standard = "OTHERS" & othersS=""; 		
								@Return(@Do(@Command([EditGotoField];"othersS");			@Prompt([Ok];"Missing Value"; "Please specify other standard requirement before proceeding!")));"");
@If(Training = "Others" & othersT=""; 		
								@Return(@Do(@Command([EditGotoField];"othersT");			@Prompt([Ok];"Missing Value"; "Please specify other training requirement before proceeding!")));"");

@If(Superior = ""; 		@Return(@Do(@Command([EditGotoField];"Superior");		@Prompt([Ok];"Missing Value"; "Please select your Superior email address before proceeding!")));"");
@If(HOD = ""; 			@Return(@Do(@Command([EditGotoField];"HOD");				@Prompt([Ok];"Missing Value"; "Please select the HOD before proceeding!")));"");

@If(desg_1 = ""; 		@Return(@Do(@Command([EditGotoField];"desg_1");			@Prompt([Ok];"Missing Value"; "Please enter your Designation before proceeding!")));"");
@If(desg_2 = ""; 		@Return(@Do(@Command([EditGotoField];"desg_2");			@Prompt([Ok];"Missing Value"; "Please enter your Superior Designation before proceeding!")));"");
