par.button:
ludb 		:="PHBSVR/PHB":"";
luview 	:= "EmployeeDetails";
Title		:="Employee Details";
Prompt	:="Select an employee";
lucol		:=8;

AllData	:=@PickList([Custom];ludb;luview;title;prompt;lucol);

empno		:=@Word(Alldata;"~";1);
empname:=@Word(Alldata;"~";2);
comp		:=@Word(Alldata;"~";3);
dept			:=@Word(Alldata;"~";4);
section		:=@Word(Alldata;"~";5);
datejoin	:=@Word(Alldata;"~";6);
desi			:=@Word(Alldata;"~";7);

FIELD EmpNo			:=@Trim(empno);
FIELD Company		:=@Trim(comp);
FIELD EmpName	:=@Trim(empname);
FIELD DateJoin		:=@Trim(datejoin);
FIELD Designation	:=@Trim(desi);
FIELD Dept				:=@Trim(dept);
FIELD Section			:=@Trim(section);

@Command([ViewRefreshFields])Select Employee

code.formula:
REM {year1   				:= @If(DateJoin=""; 0; @Year(DateJoin));
year2   				:= @Year(@Today);
month1				:= @If(DateJoin=""; 0; @Month(DateJoin));
month2				:= @Month(@Today);
day1    				:= @If(DateJoin=""; 0; @Day(DateJoin));
day2    				:= @Day(@Today);

daysinmonth 	:= @If(DateJoin=""; 0; @Select(month1;31;28;31;30;31;30;31;31;30;31;30;31));
years 				:= @If(year1 = year2; 0; year2 - year1);
tempmonth		:= @If (month1 = month2;0; month2 - month1);
months 			:= @If(day2 < day1; @Abs(tempmonth - 1); tempmonth);
days 				:= @If(day1 <= day2; day2 - day1; daysinmonth + day2 - day1);

@Text(years) + " years " + @Text(months) + " months " + @Text(days) + " days"};

temp 	:= (@Today-DateJoin)/(60*60*24);

years 	:= @Integer(temp/(365));

dmonth	:= @If(DateJoin=""; 0; @Select(@Month(DateJoin);31;28;31;30;31;30;31;31;30;31;30;31));

months	:= @If(@Modulo(temp;365)>dmonth;@Integer(@Modulo(temp;365)/dmonth);@Modulo(temp;365));

days 	:= @Modulo(@Modulo(temp;365);dmonth);

@If(@IsError(temp); "";@Text(years) + " Years " + @Text(months) + " Months " + @Text(days) + " Days")

